@extends('layouts.public') @section('title','Danh sách yêu thích') @section('content')<section class="market-page-hero compact"><small>WISHLIST</small><h1>Sản phẩm bạn đã lưu</h1><p>Wishlist lưu Product-level; hãy chọn Variant khi chuyển sang Cart nếu sản phẩm có nhiều phân loại.</p></section><section class="market-section"><form class="wishlist-filter" method="GET"><select name="availability" aria-label="Tồn kho"><option value="">Tất cả</option><option value="in_stock" @selected(request('availability')==='in_stock')>Còn hàng</option><option value="out_of_stock" @selected(request('availability')==='out_of_stock')>Hết hàng</option></select><select name="category" aria-label="Danh mục"><option value="">Danh mục</option>@foreach($categories as $category)<option value="{{ $category->id }}" @selected((string)request('category')===(string)$category->id)>{{ $category->name }}</option>@endforeach</select><select name="store" aria-label="Cửa hàng"><option value="">Cửa hàng</option>@foreach($stores as $store)<option value="{{ $store->id }}" @selected((string)request('store')===(string)$store->id)>{{ $store->name }}</option>@endforeach</select><select name="sort" aria-label="Sắp xếp"><option value="newest">Mới lưu</option><option value="price_asc" @selected(request('sort')==='price_asc')>Giá thấp → cao</option><option value="price_desc" @selected(request('sort')==='price_desc')>Giá cao → thấp</option></select><button class="market-primary">Lọc</button></form><div class="wishlist-grid">@forelse($products as $product)<article><div class="wishlist-cover">@if($product->cover_url)<img src="{{ $product->cover_url }}" alt="{{ $product->name }}">@else<span>♡</span>@endif</div><div><small>{{ $product->category_name }}</small><h2><a href="{{ route('public.products.show',$product->slug) }}">{{ $product->name }}</a></h2><p>{{ $product->store_name }}</p><strong class="market-price">{{ number_format($product->min_price_minor,0,',','.') }} ₫</strong><span>{{ (int)$product->available>0?'Còn hàng':'Hết hàng' }}</span><div class="wishlist-actions"><a href="{{ route('public.products.show',$product->slug) }}">Xem sản phẩm</a><form method="POST" action="{{ route('wishlist.cart',$product->id) }}">@csrf<button @disabled((int)$product->available<1)>Thêm vào giỏ</button></form><form method="POST" action="{{ route('wishlist.unlike',$product->id) }}">@csrf @method('DELETE')<button>Bỏ yêu thích</button></form></div></div></article>@empty<div class="market-empty"><b>♡</b><h2>Chưa có sản phẩm yêu thích</h2><a class="market-primary" href="{{ route('public.products.index') }}">Khám phá sản phẩm</a></div>@endforelse</div>{{ $products->links() }}</section>@endsection
